ALTER TABLE public.execution_notes ADD COLUMN content_type text NOT NULL DEFAULT 'file' CHECK(content_type IN ('file','draft'));
CREATE OR REPLACE FUNCTION public.execution_scope_lock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n jsonb; ws uuid; oid uuid; uid uuid; BEGIN IF TG_OP='DELETE' THEN n:=to_jsonb(OLD); ELSE n:=to_jsonb(NEW); END IF; ws:=(n->>'workspace_id')::uuid; PERFORM 1 FROM public.workspaces WHERE id=ws FOR UPDATE; IF TG_OP='INSERT' AND (n->>'created_by')::uuid IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Execution author mismatch'; END IF;
IF TG_TABLE_NAME='tasks' AND TG_OP<>'DELETE' THEN IF TG_OP='UPDATE' AND NEW.recurrence_source_id IS DISTINCT FROM OLD.recurrence_source_id THEN RAISE EXCEPTION 'Recurrence identity is immutable'; END IF; IF NEW.recurrence_source_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=NEW.recurrence_source_id AND workspace_id=NEW.workspace_id AND org_id=NEW.org_id) THEN RAISE EXCEPTION 'Recurrence scope mismatch'; END IF; END IF;
IF TG_TABLE_NAME='execution_notes' AND TG_OP<>'DELETE' THEN IF NEW.kind='member' AND NEW.user_id IS NULL THEN RAISE EXCEPTION 'Assignment requires a member'; END IF; IF length(NEW.title)>200 OR length(NEW.body)>12000 THEN RAISE EXCEPTION 'Content too long'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.execution_scope_lock() FROM PUBLIC;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['projects','tasks','campaigns','execution_notes'] LOOP EXECUTE format('CREATE TRIGGER execution_00_lock BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.execution_scope_lock()',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.execution_delete_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity_events(org_id,workspace_id,entity_type,entity_id,actor_id,action,metadata) VALUES(OLD.org_id,OLD.workspace_id,OLD.entity_type,OLD.entity_id,auth.uid(),'delete',jsonb_build_object('kind',OLD.kind,'title',OLD.title)); RETURN OLD; END $$;
REVOKE ALL ON FUNCTION public.execution_delete_history() FROM PUBLIC; CREATE TRIGGER execution_note_delete_history AFTER DELETE ON public.execution_notes FOR EACH ROW EXECUTE FUNCTION public.execution_delete_history();
REVOKE ALL ON public.projects,public.tasks,public.campaigns,public.execution_notes,public.activity_events,public.execution_conversions FROM anon;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.guard_execution()'::regprocedure) INTO definition; definition:=replace(definition,'IF NEW.kind=''asset'' AND (','IF NEW.kind=''asset'' AND NEW.content_type=''file'' AND ('); EXECUTE definition; END $$;